update content_bodies set title = '豊島 極上の癒しの時間', description = 'この動画では、豊島における極上の癒しの時間について紹介しています。豊島の美しい風景やリラックスできる環境が、視聴者に心地よい癒しを提供することを目的としています。' where id = 'lnj2xe8m5tMPPD3Wdxzsu';
