update content_bodies set title = '16バルコニー手すり', description = 'この動画では、16バルコニー手すりについて紹介しています。手すりのデザインや機能、設置方法などが説明されており、バルコニーの安全性や美観を向上させるための重要な要素としての役割が強調されています。視聴者は、手すりの選び方や取り付けのポイントについても学ぶことができ、実際の使用例や注意点が示されています。' where id = 'RoMTX0xH6YnuOOwqRTbsw';
