update content_bodies set title = '01 和敬清寂', description = 'この動画では、和敬清寂の概念について紹介しています。和敬清寂は、日本の茶道や文化において重要な価値観であり、和は調和、敬は敬意、清は清らかさ、寂は静けさを意味します。これらの要素は、茶道の実践や日常生活において、心のあり方や人との関係を深めるための指針となります。' where id = 'WauHbGGQYI_VsinKExosx';
