update content_bodies set title = '高松港紹介映像', description = 'この動画は高松港について紹介しています。高松港は香川県に位置し、四国地方の重要な交通拠点として知られています。港の美しい景観や周辺の観光スポットについても触れられており、訪れる人々にとって魅力的な場所であることが伝わります。高松港は、フェリーやクルーズ船が発着する場所でもあり、地域の経済や観光に大きく寄与しています。' where id = 'nQI9VZVCJ49l7Cpjd8j3t';
