update content_bodies set title = '【やってみたいけん！！】うちわ作り体験', description = 'この動画では、うちわ作りの体験について紹介しています。うちわは日本の伝統的な扇子であり、夏の暑さを和らげるために使われます。この体験を通じて、参加者は自分だけのオリジナルのうちわを作ることができ、楽しみながら日本の文化に触れることができます。' where id = 'acd1_OPuz5bLhxCtHAkx0';
update content_bodies set title = 'Uchiwa Making Experience', description = 'This video introduces the experience of making uchiwa, a traditional Japanese fan.' where id = 'j_wE1-eq_EtYXe6OTVPbY';
update content_bodies set title = 'やってみたいけん！！', description = 'この動画では、フォトジェニック体験について紹介しています。フォトジェニック体験は、写真映えする場所やシチュエーションを楽しむことを目的とした活動で、特にSNSでのシェアを意識した内容が多いです。視覚的に魅力的な体験を通じて、思い出を残すことができるため、多くの人々に人気があります。' where id = 'TDxYdEvW1ZBtfpwuw9SOw';
update content_bodies set title = 'Photogenic Experience You Want to Try!!', description = 'This video introduces the concept of a photogenic experience.' where id = 'HqXA6kV83kgmux5hsNF9Q';
update content_bodies set title = '魔法のほうき体験', description = 'この動画では、魔法のほうき体験について紹介しています。視聴者は、実際に魔法のほうきに乗ることができる体験を通じて、魔法の世界に触れることができます。どのような体験が待っているのか、興味を持って視聴することができる内容です。' where id = 'GvVP-IZ7z50f2XlctN6fq';
update content_bodies set title = 'Magical Broom Experience', description = 'This video introduces the magical broom experience.' where id = 'R_nzcsg0KYz7FKQFlHZLi';
update content_bodies set title = '【やってみたいけん！！】彫漆体験', description = 'この動画では、彫漆体験について紹介しています。彫漆は、漆を使った伝統的な工芸技術であり、彫刻と漆塗りを組み合わせたものです。体験を通じて、参加者はこの技術の魅力を学び、実際に手を動かして作品を作ることができます。彫漆の魅力や楽しさを感じることができる内容となっています。' where id = 'BjmrUY_yDpB48qc3qHPPE';
update content_bodies set title = 'Chisel Lacquer Experience', description = 'This video introduces the experience of chisel lacquer.' where id = 'mAcJgV3nrPqVqy1bGfxeF';
update content_bodies set title = '【やってみたいけん！！】水引体験', description = 'この動画では、水引体験について紹介しています。水引は日本の伝統的な技法で、さまざまな形や色の糸を使って美しい装飾を作ることができます。この体験を通じて、参加者は水引の基本的な技術を学び、自分だけの作品を作る楽しさを味わうことができます。動画では、実際の体験の様子や、必要な道具、作成過程などが紹介されており、興味を持った人が参加しやすい内容になっています。' where id = 'Yfs7A5kFsgT6WyXpqtOjz';
update content_bodies set title = 'Water Binding Experience', description = 'This video introduces the experience of water binding.' where id = '4gpGoEVWg9gJLoHBWA1tD';
update content_bodies set title = '豆腐づくり体験', description = 'この動画では、豆腐づくりの体験について紹介しています。豆腐は日本の伝統的な食材であり、その製造過程を学ぶことができる貴重な機会です。参加者は、豆腐の材料や作り方を学びながら、実際に手を動かして豆腐を作る楽しさを体験します。豆腐づくりは、食文化を理解するだけでなく、料理のスキルを向上させる良い機会でもあります。' where id = '8GyUEBP209LwvCoZPwnmC';
update content_bodies set title = 'Tofu Making Experience', description = 'This video introduces the experience of making tofu.' where id = '1uUmpBByG5jhYGumzQ46m';
update content_bodies set title = '四国のローカルチャーム、行ったことがありますか？ [ルート02]', description = 'この動画では、四国のローカルチャームシリーズの第2ルートを紹介し、四国が提供する独自の魅力や文化体験を視聴者に探求するよう促しています。' where id = 'ReilQyRPSr0DRDbxuzPoW';
update content_bodies set title = 'SHIKOKU LOCAL CHARM HAVE YOU BEEN THERE? [Route 02]', description = 'This video presents an introduction to the second route of the SHIKOKU LOCAL CHARM series, inviting viewers to explore the unique attractions and cultural experiences that Shikoku has to offer.' where id = 'MZubj_-abfeoLgYHAmiC_';
update content_bodies set title = '四国のローカルチャーム、行ったことがありますか？ [ルート01]', description = 'この動画では、四国のローカルチャーム「行ったことがありますか？ [ルート01]」を紹介しています。四国地域の独自の文化や美しさを示すさまざまな観光名所や体験が強調されています。' where id = 'NxZraQNRtMuUft5mqTbpF';
update content_bodies set title = 'SHIKOKU LOCAL CHARM HAVE YOU BEEN THERE? [Route 01]', description = 'This video presents an introduction to the local charms of Shikoku, focusing on Route 01. It highlights various attractions and experiences that showcase the unique culture and beauty of the Shikoku region.' where id = 'hHwwUY8tHpSeYag-DVmAD';
update content_bodies set title = '【やってみたいけん】讃岐かがり手まり体験', description = 'この動画では、讃岐かがり手まりの体験について紹介しています。讃岐かがり手まりは、香川県の伝統的な手まりで、色とりどりの糸を使って美しい模様を作り出す技術です。この体験を通じて、参加者は手まり作りの楽しさや、地域の文化に触れることができます。' where id = 'Dgb7WahMlL8VkZvILe3HZ';
