update content_bodies set title = '讃岐うどん県：四季を通じた旅', description = 'この映像は香川県のプロモーションビデオであり、四季折々の美しさや魅力を紹介しています。香川県の名物である讃岐うどんや美しい風景など、地域のユニークな魅力を探求するよう視聴者を誘うことを目的としています。' where id = 'XzV4dW9J06en5ci8n6VYG';
update content_bodies set title = 'Udon Prefecture: Traveling Through the Four Seasons', description = 'This promotional video showcases Kagawa Prefecture, highlighting its beauty and attractions throughout the four seasons. The film aims to entice viewers to explore the region''s unique offerings, including its famous udon noodles and scenic landscapes.' where id = '1whEIekhw8z3Wwcv5GqYl';
